1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  body { font-family: system-ui, sans-serif; max-width: 32rem; margin: 2rem auto; padding: 0 1rem; color: #222; }
9	  h1 { font-size: 1.5rem; }
10	  form { display: flex; gap: .5rem; }
11	  form input { flex: 1; padding: .5rem; font-size: 1rem; }
12	  form input[type="date"] { flex: 0 0 auto; }
13	  button { padding: .5rem .75rem; font-size: 1rem; cursor: pointer; }
14	  ul { list-style: none; padding: 0; margin-top: 1rem; }
15	  li { display: flex; align-items: center; gap: .5rem; padding: .5rem 0; border-bottom: 1px solid #ddd; }
16	  li span { flex: 1; overflow-wrap: anywhere; }
17	  li[data-completed="true"] span { text-decoration: line-through; color: #888; }
18	  li time { font-size: .875rem; color: #555; white-space: nowrap; }
19	  li[data-overdue="true"] { background: #fdecea; }
20	  li[data-overdue="true"] time { color: #b00020; font-weight: 600; }
21	  .filters { display: flex; gap: .5rem; margin-top: 1rem; }
22	  .filters button[aria-pressed="true"] { font-weight: 600; }
23	</style>
24	</head>
25	<body>
26	<h1>Todos</h1>
27	<form id="add-form">
28	  <input data-testid="todo-input" type="text" placeholder="What needs doing?" autocomplete="off">
29	  <input data-testid="todo-due" type="date" aria-label="Due date">
30	  <button data-testid="todo-add" type="submit">Add</button>
31	</form>
32	<div class="filters">
33	  <button data-testid="filter-all" type="button" data-filter="all" aria-pressed="true">All</button>
34	  <button data-testid="filter-active" type="button" data-filter="active" aria-pressed="false">Active</button>
35	  <button data-testid="filter-completed" type="button" data-filter="completed" aria-pressed="false">Completed</button>
36	</div>
37	<ul data-testid="todo-list"></ul>
38	<script>
39	(function () {
40	  var KEY = 'todos';
41	  var input = document.querySelector('[data-testid="todo-input"]');
42	  var dueInput = document.querySelector('[data-testid="todo-due"]');
43	  var list = document.querySelector('[data-testid="todo-list"]');
44	  var form = document.getElementById('add-form');
45	  var filterButtons = document.querySelectorAll('[data-filter]');
46	  var filter = 'all';
47	
48	  function load() {
49	    try {
50	      var data = JSON.parse(localStorage.getItem(KEY));
51	      return Array.isArray(data) ? data : [];
52	    } catch (e) {
53	      return [];
54	    }
55	  }
56	
57	  function save() {
58	    try { localStorage.setItem(KEY, JSON.stringify(todos)); } catch (e) {}
59	  }
60	
61	  function newId() {
62	    if (window.crypto && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
63	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
64	  }
65	
66	  // Project rule: due dates are plain YYYY-MM-DD strings, read as LOCAL calendar dates.
67	  // Never parse them through Date/UTC. Overdue = due date strictly before today's local date.
68	  function validDue(value) {
69	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : null;
70	  }
71	
72	  function pad(n) { return (n < 10 ? '0' : '') + n; }
73	
74	  function localToday(now) {
75	    return now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
76	  }
77	
78	  // Zero-padded YYYY-MM-DD strings sort lexicographically in date order.
79	  function isOverdue(due, today) {
80	    return !!validDue(due) && due < today;
81	  }
82	
83	  // Project rule: active todos first, completed below; insertion order within each group.
84	  function visibleTodos(all, f) {
85	    var active = all.filter(function (t) { return !t.completed; });
86	    var done = all.filter(function (t) { return !!t.completed; });
87	    if (f === 'active') return active;
88	    if (f === 'completed') return done;
89	    return active.concat(done);
90	  }
91	
92	  function render() {
93	    list.textContent = '';
94	    renderedDay = localToday(new Date());
95	    filterButtons.forEach(function (b) {
96	      b.setAttribute('aria-pressed', String(b.dataset.filter === filter));
97	    });
98	    visibleTodos(todos, filter).forEach(function (todo) {
99	      var li = document.createElement('li');
100	      li.setAttribute('data-testid', 'todo-item');
101	      li.setAttribute('data-completed', String(!!todo.completed));
102	      li.setAttribute('data-overdue', String(isOverdue(todo.due, renderedDay)));
103	      li.dataset.id = todo.id;
104	
105	      var toggle = document.createElement('input');
106	      toggle.setAttribute('data-testid', 'todo-toggle');
107	      toggle.type = 'checkbox';
108	      toggle.checked = !!todo.completed;
109	      toggle.setAttribute('aria-label', 'Mark complete');
110	      toggle.addEventListener('change', function () {
111	        todo.completed = toggle.checked;
112	        save();
113	        render();
114	      });
115	
116	      var text = document.createElement('span');
117	      text.setAttribute('data-testid', 'todo-text');
118	      text.textContent = todo.text;
119	
120	      var del = document.createElement('button');
121	      del.setAttribute('data-testid', 'todo-delete');
122	      del.type = 'button';
123	      del.textContent = 'Delete';
124	      del.addEventListener('click', function () {
125	        todos = todos.filter(function (t) { return t.id !== todo.id; });
126	        save();
127	        render();
128	      });
129	
130	      li.appendChild(toggle);
131	      li.appendChild(text);
132	      if (validDue(todo.due)) {
133	        var due = document.createElement('time');
134	        due.setAttribute('data-testid', 'todo-due-date');
135	        due.dateTime = todo.due;
136	        due.textContent = 'Due ' + todo.due;
137	        li.appendChild(due);
138	      }
139	      li.appendChild(del);
140	      list.appendChild(li);
141	    });
142	  }
143	
144	  var todos = load();
145	  var renderedDay = '';
146	
147	  form.addEventListener('submit', function (e) {
148	    e.preventDefault();
149	    var text = input.value.trim();
150	    if (!text) return;
151	    todos.push({ id: newId(), text: text, completed: false, createdAt: Date.now(), due: validDue(dueInput.value) });
152	    save();
153	    render();
154	    input.value = '';
155	    dueInput.value = '';
156	    input.focus();
157	  });
158	
159	  filterButtons.forEach(function (b) {
160	    b.addEventListener('click', function () {
161	      filter = b.dataset.filter;
162	      render();
163	    });
164	  });
165	
166	  // Re-render when the local calendar day changes so overdue flags stay current.
167	  setInterval(function () {
168	    if (localToday(new Date()) !== renderedDay) render();
169	  }, 60000);
170	
171	  render();
172	})();
173	</script>
174	</body>
175	</html>
